"""Merge layered INI files: a key in a later file replaces the same key before it."""

from __future__ import annotations

import configparser

Config = dict[str, dict[str, str]]


def read_layer(text: str) -> Config:
    """Parse one INI text into {section: {key: value}}, keeping keys as written."""
    parser = configparser.ConfigParser(interpolation=None)
    parser.optionxform = str  # keep key case as written
    parser.read_string(text)
    return {name: dict(parser[name]) for name in parser.sections()}


def merge_layers(layers: list[Config]) -> Config:
    """Merge parsed layers in order; later values replace earlier ones."""
    merged: Config = {}
    for layer in layers:
        for section, values in layer.items():
            merged.setdefault(section, {}).update(values)
    return merged


def merge_files(paths: list[str]) -> Config:
    """Read the INI files in order and merge them."""
    layers = []
    for path in paths:
        with open(path, encoding="utf-8") as handle:
            layers.append(read_layer(handle.read()))
    return merge_layers(layers)


def render(config: Config) -> str:
    """INI text for a config: sections in order, one "key = value" line per key."""
    blocks = []
    for section, values in config.items():
        lines = [f"[{section}]"] + [f"{key} = {value}" for key, value in values.items()]
        blocks.append("\n".join(lines))
    return "\n\n".join(blocks) + "\n"

